  if(config.structure==='music'){var piano=root.querySelector('.zrs-structure-art');piano.removeAttribute('aria-hidden');var pianoKeys=Array.from(piano.querySelectorAll('i'));pianoKeys.forEach(function(key,index){key.className='zrs-piano-key';key.tabIndex=0;key.setAttribute('role','button');key.setAttribute('aria-label','琴键 '+(index+1));function activate(){pianoKeys.forEach(function(item){item.classList.toggle('is-active',item===key);});window.setTimeout(function(){key.classList.remove('is-active');},180);}key.addEventListener('click',activate);key.addEventListener('keydown',function(event){if(event.key!=='Enter'&&event.key!==' ')return;event.preventDefault();activate();});});}
  if(config.structure==='quest'){var map=root.querySelector('.zrs-structure-art');map.removeAttribute('aria-hidden');var questValues=records[config.pages[0].id]||[];[['当前区域',questValues[0]],['下一节点',questValues[3]],['任务目标',questValues[1]]].forEach(function(item){var node=make('button','zrs-map-node',item[0]);node.type='button';node.title=String(item[1]||item[0]);node.addEventListener('click',function(){map.querySelectorAll('.zrs-map-node').forEach(function(button){button.classList.toggle('is-active',button===node);});});map.append(node);});}
  if(phoneMode&&config.phoneDesktop.wallpaperUrl){var wallpaper=make('img');wallpaper.src=config.phoneDesktop.wallpaperUrl;wallpaper.alt='';wallpaper.draggable=false;wallpaper.style.objectPosition=config.phoneDesktop.wallpaperPositionX+'% '+config.phoneDesktop.wallpaperPositionY+'%';wallpaper.addEventListener('error',function(){wallpaper.remove();});root.querySelector('.zrs-phone-wallpaper').append(wallpaper);}
  var mediaHost=root.querySelector('.zrs-structure-head');
  var hasAvatarField=config.sharedFields.some(function(field){return field.kind==='avatar';})||config.pageFields.some(function(field){return field.kind==='avatar';})||config.pages.some(function(page){return (page.fields||[]).some(function(field){return field.kind==='avatar';});});
  function addImage(url,className,alt){if(!url)return null;var img=make('img',className);img.src=url;img.alt=alt||'';img.loading='lazy';img.referrerPolicy='no-referrer';img.addEventListener('error',function(){img.remove();});mediaHost.append(img);return img;}
  if(config.media.avatarUrl&&config.structure!=='forum'&&!hasAvatarField){addImage(config.media.avatarUrl,'zrs-avatar',config.media.imageAlt);var copy=make('div','zrs-media-copy');copy.append(make('b','',config.structureName),make('small','',config.media.avatarSource==='character'?'当前角色头像':config.media.avatarSource==='user'?'当前 user 头像':'自定义头像'));mediaHost.append(copy);}
